def settled_reachable_neck(s: object) -> dict[str, object]:
    x = cast(PickupScene, s)
    palm = x.assembly.robot.hand.origin.pose.pos
    goal = x.assembly.obj.pose @ n.asarray((0.018, -0.045, 0.350))
    distance = n.sqrt(n.sum((palm - goal) ** 2))
    speed = x.contact_observations["relative_speed_m_s"].get().x[0]
    return {
        "reachable_neck_region": KeepBelow(distance, 0.060),
        "settled_relative_motion": KeepBelow(speed, 0.025),
    }

